        raise ValueError((
            "The following parameter(s) are not valid: %s\n"
            "The valid parameters are obj, item, exclude_paths, exclude_types,\n"
            "case_sensitive, match_string and verbose_level."
        ) % ', '.join(kwargs.keys()))

